5: const args = process.argv.slice(2);
6: const portIndex = args.indexOf('--port');
7: const port = Number(portIndex >= 0 ? args[portIndex + 1] : process.env.PORT || 3000);
8: const root = process.cwd();
9: const types = { '.css': 'text/css', '.html': 'text/html', '.js': 'text/javascript', '.json': 'application/json' };
