11: createServer((request, response) => {
12:   const pathname = decodeURIComponent(new URL(request.url, 'http://localhost').pathname);
13:   const relative = pathname === '/' ? 'index.html' : normalize(pathname).replace(/^[/\\]+/, '');
14:   const file = join(root, relative);
15:   if (!file.startsWith(root) || !existsSync(file)) {
16:     response.writeHead(404).end('Not found');
17:     return;
18:   }
19:   response.writeHead(200, { 'content-type': `${types[extname(file)] || 'application/octet-stream'}; charset=utf-8` });
20:   createReadStream(file).pipe(response);
21: }).listen(port, '0.0.0.0', () => console.log(`Mock OpenCode project listening on ${port}`));

